@Bean
public RestTemplate restTemplate() {
    RequestConfig config = RequestConfig.custom()
            .setConnectTimeout(10_000)      // 5s → 10s：跨机房 TLS 握手时间不稳
            .setSocketTimeout(20_000)       // 10s → 20s：上游批量写订单耗时翻倍
            .setConnectionRequestTimeout(10_000)
            .build();
    // 连接池同步放大：10 个连接、空闲 5 分钟回收
    PoolingHttpClientConnectionManager cm =
            new PoolingHttpClientConnectionManager(5, TimeUnit.MINUTES);
    cm.setMaxTotal(10);
    cm.setDefaultMaxPerRoute(10);
    CloseableHttpClient client = HttpClients.custom()
            .setConnectionManager(cm)
            .setDefaultRequestConfig(config)
            .evictExpiredConnections()
            .build();
    HttpComponentsClientHttpRequestFactory factory =
            new HttpComponentsClientHttpRequestFactory(client);
    return new RestTemplate(factory);
}

public void pushOrder(OrderSyncReq req) {
    PriceSysResult result = priceSysClient.pushOrder(req);
    // 上游返回 null 不允许继续往下走，边界处立刻变成可识别的业务异常
    if (result == null) {
        throw new BizException(ErrorCode.PRICE_SYS_ERROR, "价格系统调用失败，请稍后重试");
    }
    // 成功判定收紧成双条件：既要状态成功，也要带业务单号
    if (!result.isSuccess() || StringUtils.isBlank(result.getOrderNo())) {
        log.error("pushOrder rejected, reqNo: {}, success: {}, orderNo: {}",
                req.getReqNo(), result.isSuccess(), result.getOrderNo());
        throw new BizException(ErrorCode.PRICE_SYS_ERROR,
                StringUtils.defaultIfBlank(result.getMsg(), "价格系统未返回单号"));
    }
    log.info("pushOrder success, reqNo: {}, orderNo: {}", req.getReqNo(), result.getOrderNo());
}
